-- =========================================================
-- Migration "Explorer France" (epic #11-#17) - généré le 21/11/2026
-- A exécuter dans l'éditeur SQL Supabase du projet bivouac-app.
-- =========================================================

-- 1) Table points_interet (#12)
create table if not exists public.points_interet (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  region text not null,
  category text not null,
  lat double precision not null,
  lon double precision not null,
  photo_urls jsonb default '[]'::jsonb,
  description_courte text,
  description_longue text,
  ambiance_tags jsonb default '[]'::jsonb,
  best_duration text,
  best_season text,
  practical_tips text,
  how_to_get_there text,
  popularity text default 'moyenne', -- 'faible' | 'moyenne' | 'forte'
  hidden_gem boolean default false,
  created_at timestamptz default now()
);

alter table public.points_interet enable row level security;

drop policy if exists "points_interet_select_all" on public.points_interet;
create policy "points_interet_select_all" on public.points_interet
  for select using (true);

-- Écriture réservée (pas d'UI d'ajout public pour le proto) : pas de policy insert/update/delete
-- pour anon/authenticated. Les insertions se font ici via l'éditeur SQL (rôle service/owner).

grant select on public.points_interet to anon, authenticated;

-- 2) Colonnes poi_id (#14, #15)
alter table public.comments add column if not exists poi_id uuid references public.points_interet(id);
alter table public.trip_stops add column if not exists poi_id uuid references public.points_interet(id);

-- 3) Favoris unifiés (#16) - Option A : extension de favorites
-- favorites avait (user_id, spot_id) en clé primaire composite : spot_id est donc NOT NULL
-- implicitement et ne peut pas devenir nullable tant qu'il fait partie de la PK.
-- On remplace par un id de substitution (uuid) + contraintes d'unicité partielles.
alter table public.favorites add column if not exists id uuid default gen_random_uuid();
update public.favorites set id = gen_random_uuid() where id is null;
alter table public.favorites alter column id set not null;

alter table public.favorites add column if not exists item_type text default 'spot'; -- 'spot' | 'poi'
alter table public.favorites add column if not exists poi_id uuid references public.points_interet(id);

alter table public.favorites drop constraint if exists favorites_pkey;
alter table public.favorites add constraint favorites_pkey primary key (id);

alter table public.favorites alter column spot_id drop not null;

drop index if exists favorites_user_spot_unique;
create unique index favorites_user_spot_unique on public.favorites (user_id, spot_id) where spot_id is not null;
drop index if exists favorites_user_poi_unique;
create unique index favorites_user_poi_unique on public.favorites (user_id, poi_id) where poi_id is not null;

-- 4) Seed des lieux éditoriaux (#11)
insert into public.points_interet
  (slug, name, region, category, lat, lon, description_courte, description_longue, ambiance_tags, best_duration, best_season, practical_tips, how_to_get_there, popularity, hidden_gem)
values
  ('annecy', 'Annecy', 'Auvergne-Rhône-Alpes', 'ville', 45.8992, 6.1294, 'La « Venise des Alpes », vieille ville à canaux au bord d''un lac parmi les plus purs d''Europe.', 'Annecy doit son surnom à son centre historique traversé de canaux, bordé de maisons colorées et dominé par le Palais de l''Isle et le château médiéval. Le lac d''Annecy, à deux pas, offre baignade, pédalos et un tour complet d''environ 30 km entre montagnes et villages. Les quais et le marché du centre ancien se prêtent à une balade à pied, incontournable mais compliquée en camping-car.', '["lac","montagne","baignade","romantique"]'::jsonb, '1 à 2 jours', 'Mai à septembre', 'Se garer avec un camping-car dans ou aux abords du centre-ville d''Annecy est très compliqué : mieux vaut utiliser une aire dédiée en périphérie (comme celle de Colmyr, gratuite toute l''année) et rejoindre le centre à pied, vélo ou bus.', 'Accès par l''A41 (sortie Annecy) ou l''A43 depuis Lyon/Chambéry. Gare TGV directe depuis Paris et Lyon.', 'forte', false),
  ('mont-saint-michel', 'Mont-Saint-Michel', 'Normandie', 'monument', 48.6361, -1.5115, 'Îlot rocheux et abbaye médiévale emblématiques, cernés par les plus grandes marées d''Europe continentale.', 'Silhouette visible à des kilomètres, le Mont-Saint-Michel surgit de sa baie au gré des marées. L''abbaye perchée, les ruelles pentues et les remparts se visitent à pied depuis les grands parkings continentaux reliés par navette gratuite. Le site est un Grand Site de France inscrit à l''UNESCO, à ne pas confondre avec les parkings payants attenants.', '["patrimoine","marée","incontournable","famille"]'::jsonb, 'Demi-journée à 1 jour', 'Toute l''année, idéalement hors juillet-août pour éviter l''affluence', 'Le stationnement sur le grand parking est payant mais le séjour nocturne y est toléré ; impossible en revanche d''y rester garé pendant la visite comme aire d''hébergement. Plusieurs aires et campings dédiés aux camping-cars existent à proximité (Beauvoir), avec navette gratuite vers le Mont.', 'A84 puis D976 depuis Rennes ou Caen. Gare SNCF la plus proche : Pontorson, puis navette Midibus.', 'forte', false),
  ('gouffre-de-padirac', 'Gouffre de Padirac', 'Occitanie', 'site naturel', 44.8339, 1.7406, 'Immense gouffre souterrain du Lot où l''on descend à 103 m de profondeur avant une balade en barque sur une rivière souterraine.', 'Découvert en 1889, le Gouffre de Padirac est le premier site souterrain naturel de France avec près de 500 000 visiteurs par an. La visite guidée combine marche, ascenseurs et une traversée en barque menée par un batelier sur la « rivière plane ». Un monde minéral spectaculaire, incontournable lors d''un passage dans la vallée de la Dordogne.', '["grotte","insolite","famille","fraîcheur"]'::jsonb, '2 à 3 heures', 'Avril à novembre (fermé l''hiver)', 'Parking gratuit dédié aux camping-cars (P2), mais stationnement nocturne interdit sur place (22h-8h) ; une aire de camping-car existe à Trémoulières, à 2 km. Arriver tôt en haute saison, la visite se fait par petits groupes toutes les 30 minutes.', 'Par la D673 puis D90, à 30 min de Rocamadour et Brive-la-Gaillarde.', 'forte', false),
  ('gorges-du-verdon', 'Gorges du Verdon', 'Provence-Alpes-Côte d''Azur', 'site naturel', 43.8434, 6.2219, 'Le plus grand canyon d''Europe, aux eaux turquoise, bordé de deux routes panoramiques entre Castellane et Moustiers-Sainte-Marie.', 'Les Gorges du Verdon se parcourent par la route des Crêtes (rive droite) ou la Corniche Sublime (rive gauche), ponctuées de points de vue vertigineux. Canoë, baignade au lac de Sainte-Croix et randonnée complètent la découverte. Le village perché de Moustiers-Sainte-Marie, réputé pour sa faïence, en est la porte d''entrée la plus pittoresque.', '["canyon","randonnée","baignade","panorama"]'::jsonb, '2 à 4 jours', 'Mai à septembre', 'Routes touristiques étroites et sinueuses : roulez lentement et partagez la chaussée avec cyclistes et motards. Castellane et Moustiers-Sainte-Marie disposent d''aires de services pour camping-cars ; prévoir les grands axes pour les véhicules les plus longs.', 'Accès par Castellane (D952) ou Aups/Moustiers (D71-D952) depuis l''A51 (Marseille-Aix).', 'forte', false),
  ('saint-malo', 'Saint-Malo', 'Bretagne', 'ville', 48.6494, -2.0257, 'Cité corsaire fortifiée, ceinturée de remparts du XIVe siècle offrant un tour de ville face à la mer d''Émeraude.', 'Reconstruite après la Seconde Guerre mondiale à l''identique, la vieille ville intra-muros de Saint-Malo s''explore en suivant les remparts sur environ 2 km, du château à la Tour Bidouane puis au Bastion de la Hollande. La plage de Bon-Secours, en piscine d''eau de mer à marée basse, est un passage obligé juste en contrebas.', '["remparts","mer","histoire","corsaire"]'::jsonb, '1 journée', 'Avril à octobre', 'Plusieurs aires de camping-car existent à l''entrée de la ville (parking Paul Féval, Les Ilots) avec navette ou bus vers l''intramuros ; éviter de chercher à se garer directement dans la cité historique.', 'Par la RN137 depuis Rennes (1h) ou la D137 depuis Dinan.', 'forte', false),
  ('dune-du-pilat', 'Dune du Pilat', 'Nouvelle-Aquitaine', 'site naturel', 44.5896, -1.2156, 'La plus haute dune de sable d''Europe, à l''entrée du Bassin d''Arcachon, avec vue sur l''océan et la forêt landaise.', 'Culminant à plus de 100 mètres, la Dune du Pilat avance d''environ 5 mètres par an vers la forêt sous l''effet du vent. L''ascension, sans escalier mais sportive dans le sable, est récompensée par un panorama à 360° sur le Bassin d''Arcachon, le Banc d''Arguin et l''océan Atlantique. Un Grand Site de France protégé, accueillant près de 2 millions de visiteurs par an.', '["dune","océan","coucher de soleil","sport"]'::jsonb, '2 à 3 heures', 'Printemps et été pour la météo, hors juillet-août pour éviter la foule', 'Stationnement camping-car payant (tarif spécifique plus élevé que les voitures) et interdit la nuit ; stationnement sauvage strictement prohibé aux abords (amende). Privilégier une arrivée matinale en haute saison, le parking sature vite.', 'Par la D218 depuis Arcachon ou La Teste-de-Buch ; navette Dune Express en juillet-août.', 'forte', false),
  ('colmar', 'Colmar', 'Grand Est', 'ville', 48.0794, 7.3585, 'Capitale des vins d''Alsace, célèbre pour son quartier de la Petite Venise aux maisons à colombages colorées.', 'Colmar enchante par ses canaux bordés de maisons à pans de bois fleuries, en particulier dans le quartier de la Petite Venise. Le musée Unterlinden, la vieille ville et la proximité de la route des vins d''Alsace en font une étape culturelle et gourmande. Les marchés de Noël, parmi les plus réputés de France, transforment la ville en décor féerique en fin d''année.', '["colombages","canaux","vin","romantique"]'::jsonb, '1 à 2 jours', 'Avril à octobre, ou décembre pour les marchés de Noël', 'Aire de camping-car dédiée au port de plaisance de Colmar (environ 20 minutes à pied du centre historique), avec parc clôturé ; réserver tôt en période de marchés de Noël, l''affluence et les places limitées se font sentir.', 'Sortie A35 "Colmar", à 30 min de Strasbourg et Mulhouse.', 'forte', false),
  ('cirque-de-gavarnie', 'Cirque de Gavarnie', 'Occitanie', 'site naturel', 42.6936, -0.0094, 'Amphithéâtre naturel classé à l''UNESCO dans les Pyrénées, que Victor Hugo décrivait comme le « Colosseum de la nature ».', 'Depuis le village de Gavarnie, un sentier balisé de 2 à 2h30 de marche aller-retour, peu technique, mène au pied de la Grande Cascade, la plus haute d''Europe avec ses 417 mètres de chute. Les parois calcaires du cirque, hautes de 1500 mètres, dominent un paysage glaciaire exceptionnel, accessible aussi à cheval ou à dos d''âne en été.', '["montagne","randonnée","cascade","patrimoine UNESCO"]'::jsonb, 'Demi-journée (randonnée de 4 à 5h aller-retour)', 'Juin à octobre (itinéraire déconseillé en hiver et au printemps, risque d''avalanches)', 'Se garer au parking du village de Gavarnie (payant en saison) ; un bus dessert aussi le village depuis Lourdes en été. Partir tôt le matin pour profiter de la lumière, éviter la chaleur et devancer l''affluence de juillet-août.', 'Par la D921 depuis Lourdes via Luz-Saint-Sauveur et Gèdre (environ 1h15).', 'moyenne', true),
  ('calanques-de-cassis', 'Calanques de Cassis', 'Provence-Alpes-Côte d''Azur', 'site naturel', 43.214, 5.539, 'Criques d''eau turquoise encaissées entre falaises blanches, aux portes de Cassis et Marseille.', 'Port-Pin et En-Vau, accessibles à pied depuis Cassis (15 à 60 minutes de marche selon la calanque), offrent des eaux cristallines nichées entre pinèdes et parois calcaires. Le Parc national des Calanques, créé en 2012, protège un territoire classé parmi les plus fréquentés de France, avec plus de 3 millions de visiteurs par an.', '["mer","falaises","randonnée","baignade"]'::jsonb, 'Demi-journée à 1 jour', 'Mai à septembre, en dehors des pics de risque incendie', 'Accès motorisé très réglementé et souvent fermé en été (du 1er juin au 30 septembre, arrêté préfectoral anti-incendie) : mieux vaut se garer à Cassis ou La Ciotat et marcher, certaines calanques (Sugiton) nécessitant même une réservation en ligne. Vérifier le niveau de risque incendie du jour avant de partir.', 'Sortie "Cassis" sur l''A50 depuis Marseille ou Toulon ; gare SNCF de Cassis.', 'forte', false),
  ('sarlat-la-caneda', 'Sarlat-la-Canéda', 'Nouvelle-Aquitaine', 'ville', 44.89, 1.216, 'Capitale du Périgord noir, cité médiévale à la plus forte densité de monuments historiques au monde.', 'Ruelles pavées, maisons à colombages et hôtels particuliers en pierre ocre composent le décor exceptionnellement préservé de Sarlat, souvent utilisé comme plateau de cinéma. Le marché couvert du samedi matin, haut lieu de la gastronomie périgourdine (foie gras, noix, cabécou), anime tout le centre ancien. Point de départ idéal pour la vallée de la Dordogne et ses châteaux.', '["médiéval","gastronomie","marché","patrimoine"]'::jsonb, '1 à 2 jours', 'Avril à octobre ; marché du samedi matin incontournable', 'Aire de camping-car communale au centre, sur l''ancien camping municipal, à distance de marche du centre historique. La ville se visite entièrement à pied, prévoir de laisser le véhicule à l''aire dès l''arrivée.', 'Par la D704 ou D703 ; gare SNCF de Sarlat-la-Canéda, aéroports de Brive et Bergerac à proximité.', 'moyenne', false),
  ('pointe-du-raz', 'Pointe du Raz', 'Bretagne', 'site naturel', 48.0397, -4.7339, 'Éperon rocheux à l''extrémité du Finistère, l''un des plus beaux sites naturels de Bretagne face au Raz de Sein.', 'Classée Grand Site de France, la Pointe du Raz offre un sentier côtier sur le GR34 jusqu''au sémaphore, avec vue sur le phare de la Vieille et l''île de Sein. Les falaises battues par les vents et les embruns en font un lieu de visite spectaculaire, surtout à la tombée du jour lors des visites crépusculaires organisées sur place.', '["falaises","mer","randonnée","coucher de soleil"]'::jsonb, '2 à 3 heures', 'Toute l''année, idéal au printemps et en été pour la lumière du soir', 'Stationnement payant toute l''année en haute saison (environ 8€/jour, tarif identique voitures et camping-cars), compter 20 minutes de marche depuis le parking jusqu''à la pointe. Une navette relie en été la Pointe du Raz à la Pointe du Van.', 'Par la D784 puis D8 depuis Audierne ou Douarnenez.', 'moyenne', false),
  ('gorges-de-lardeche', 'Gorges de l''Ardèche', 'Auvergne-Rhône-Alpes', 'site naturel', 44.4057, 4.3968, 'Canyon calcaire de plus de 30 km creusé par la rivière Ardèche, célèbre pour son arche naturelle du Pont d''Arc.', 'La route touristique des Gorges de l''Ardèche (D290), classée réserve naturelle nationale, serpente entre points de vue vertigineux depuis Vallon-Pont-d''Arc jusqu''à Saint-Martin-d''Ardèche. Le Pont d''Arc, arche naturelle sculptée par la rivière, marque l''entrée du site et se découvre aussi en canoë. Spots de baignade réputés à Balazuc et Vogüé.', '["canyon","canoë","baignade","panorama"]'::jsonb, '1 à 2 jours', 'Mai à octobre', 'La route touristique se conduit aussi en camping-car mais certains passages restent délicats pour les grands véhicules : rouler prudemment. Camping sauvage interdit dans la réserve naturelle, seul le bivouac minimaliste y est toléré ; plusieurs aires de service existent à Vallon-Pont-d''Arc.', 'Par la D579 ou D104 depuis Montélimar ou Aubenas.', 'forte', false),
  ('collioure', 'Collioure', 'Occitanie', 'ville', 42.5256, 3.0836, 'Village catalan haut en couleurs sur la Côte Vermeille, qui inspira Matisse et Derain au début du XXe siècle.', 'Dominé par son château royal et son clocher planté dans la mer, Collioure déroule ses ruelles pastel et ses barques catalanes colorées le long d''une petite baie méditerranéenne. Le village, berceau du fauvisme, a conservé l''ambiance qui a séduit les peintres, entre criques de galets et anchois artisanaux.', '["méditerranée","village catalan","art","plage"]'::jsonb, '1 journée', 'Mai à octobre', 'Stationnement en centre-ville interdit aux camping-cars (barrières) : direction l''aire municipale du Cap Dourats, à environ 2 km du centre, reliée par navette gratuite en été. Prévoir l''affluence estivale, le village est très fréquenté en juillet-août.', 'Sortie 14 "Collioure" depuis l''A9 au sud de Perpignan.', 'moyenne', true),
  ('puy-de-dome', 'Puy de Dôme', 'Auvergne-Rhône-Alpes', 'site naturel', 45.7722, 2.9657, 'Volcan emblématique de la chaîne des Puys, seul site du patrimoine mondial UNESCO accessible à tous via un train à crémaillère.', 'Culminant à 1465 mètres, le Puy de Dôme se gravit en 15 minutes à bord du Panoramique des Dômes, un train électrique à crémaillère entièrement accessible, ou à pied par le chemin des Muletiers pour les plus sportifs. Au sommet, un panorama à 360° embrasse la chaîne des Puys, classée à l''UNESCO parmi les 80 volcans du monde, ainsi que les vestiges d''un temple gallo-romain dédié à Mercure.', '["volcan","panorama","randonnée","patrimoine UNESCO"]'::jsonb, 'Demi-journée', 'Avril à octobre (le train fonctionne toute l''année, conditions hivernales variables)', 'Grand parking au pied du site (gare de la Font de l''Arbre) adapté aux camping-cars ; réserver son billet de train à l''avance en haute saison, l''affluence est importante l''été.', 'Par la D941A ou D68 depuis Clermont-Ferrand (environ 15 km).', 'forte', false),
  ('etretat', 'Étretat', 'Normandie', 'site naturel', 49.7075, 0.2044, 'Falaises de craie blanche et arches naturelles spectaculaires sur la Côte d''Albâtre, immortalisées par Monet et Maupassant.', 'Les trois arches naturelles d''Étretat (Amont, Aval, Manneporte) et l''aiguille de craie qui les accompagne forment l''un des paysages côtiers les plus photographiés de France. Des sentiers sur les falaises, de part et d''autre de la plage de galets, offrent des points de vue vertigineux sur la Manche. La maison d''Arsène Lupin et le centre-ville complètent la visite.', '["falaises","mer","randonnée","peinture impressionniste"]'::jsonb, 'Demi-journée à 1 jour', 'Avril à octobre', 'Aire de camping-car payante juste à l''entrée de la ville, à 1,5 km des falaises (environ 15 minutes à pied) ; prévoir d''arriver tôt le matin en été, les parkings du centre saturent vite et les emplacements sur l''aire se remplissent rapidement.', 'Par la D940 depuis Le Havre (30 min) ou Fécamp.', 'forte', false),
  ('roussillon-sentier-des-ocres', 'Roussillon et le Sentier des Ocres', 'Provence-Alpes-Côte d''Azur', 'site naturel', 43.9018, 5.2946, 'Village perché classé parmi les Plus Beaux Villages de France, au-dessus d''un ancien gisement d''ocre aux couleurs flamboyantes.', 'Les façades du village de Roussillon déclinent toute la palette des ocres locales, du jaune pâle au rouge profond. En contrebas, le Sentier des Ocres serpente dans d''anciennes carrières à ciel ouvert, entre falaises minérales et pins, sur un parcours aménagé de passerelles et belvédères. L''écomusée Ôkhra, à proximité, raconte l''histoire industrielle du site.', '["village perché","géologie","randonnée","couleurs"]'::jsonb, '2 à 3 heures', 'Toute l''année, lumière la plus spectaculaire en fin de journée', 'Le sentier compte environ 350 marches et n''est pas adapté aux poussettes ni aux personnes à mobilité réduite ; plusieurs parkings (dont un pour cars) existent au village et sur le site, entrée payante réglée sur place.', 'Par la D105 depuis Apt (environ 10 km), au cœur du Luberon.', 'moyenne', true),
  ('baie-de-somme', 'Baie de Somme', 'Hauts-de-France', 'site naturel', 50.1853, 1.6356, 'Vaste estuaire classé parmi les plus belles baies du monde, où l''on observe des colonies de phoques sauvages au fil des marées.', 'Entre Saint-Valery-sur-Somme, Le Crotoy et la Pointe du Hourdel, la Baie de Somme déroule 70 km² de vasières, prés salés et bancs de sable où se reposent phoques veaux-marins et gris. La traversée guidée de la baie à marée basse, le Parc du Marquenterre pour l''observation ornithologique et le petit train à vapeur comptent parmi les incontournables.', '["nature","phoques","marée","oiseaux"]'::jsonb, '1 à 2 jours', 'Toute l''année, l''automne pour la pêche à pied et les migrations d''oiseaux', 'Tout se cale sur les horaires de marée (coefficients parmi les plus élevés d''Europe) : vérifier les horaires avant de planifier la journée, en particulier pour l''observation des phoques à la Pointe du Hourdel, visibles surtout à marée descendante. Garder ses distances, l''approche des phoques est interdite.', 'Par la D940 ou D3 depuis Abbeville ; aire de camping-car à Saint-Valery-sur-Somme et au Crotoy.', 'moyenne', true),
  ('gorges-du-tarn', 'Gorges du Tarn', 'Occitanie', 'site naturel', 44.3614, 3.4214, 'Canyon creusé par le Tarn entre les Causses, bordé de villages médiévaux et de falaises propices à la baignade et au canoë.', 'De Florac au Rozier, la route des Gorges du Tarn longe la rivière au pied de falaises calcaires impressionnantes, ponctuée de villages comme Sainte-Énimie ou La Malène. En été, les eaux du Tarn se prêtent à la baignade et au canoë, tandis que les Causses environnants offrent des panoramas typiques des grands espaces du Sud-Massif Central.', '["canyon","rivière","baignade","villages médiévaux"]'::jsonb, '2 à 3 jours', 'Juin à septembre (crues possibles le reste de l''année, "épisodes cévenols")', 'Routes étroites et sinueuses au cœur des gorges, circulation parfois difficile pour les plus grands véhicules en pleine saison ; de nombreux campings bord de rivière entre Sainte-Énimie et Florac accueillent les camping-cars.', 'Sortie "Gorges du Tarn" sur l''A75 à Aguessac, puis D907.', 'moyenne', true)
on conflict (slug) do update set
  name = excluded.name, region = excluded.region, category = excluded.category,
  lat = excluded.lat, lon = excluded.lon,
  description_courte = excluded.description_courte, description_longue = excluded.description_longue,
  ambiance_tags = excluded.ambiance_tags, best_duration = excluded.best_duration, best_season = excluded.best_season,
  practical_tips = excluded.practical_tips, how_to_get_there = excluded.how_to_get_there,
  popularity = excluded.popularity, hidden_gem = excluded.hidden_gem;

